import java.nio.file.*;import java.util.*;import java.util.regex.*;import java.io.*;
/** Build gate for constant branches and statements textually placed after unconditional terminals. */
public final class UnreachableBranchCheck{
 private static final Pattern CONSTANT=Pattern.compile("\\b(?:if\\s*\\(\\s*(?:true|false)\\s*\\)|while\\s*\\(\\s*false\\s*\\))");
 public static void main(String[]args)throws Exception{Path root=Path.of(args[0]),client=Path.of(args[1]);List<String>failures=new ArrayList<>();scan(root.resolve("server"),failures);scan(client.resolve("assets"),failures);Path out=root.resolve("work/audit/dead02-unreachable-branches.txt");Files.createDirectories(out.getParent());Files.writeString(out,failures.isEmpty()?"DEAD02 passed: no constant branch or post-terminal statement found.\n":String.join("\n",failures)+"\n");if(!failures.isEmpty())throw new IllegalStateException("unreachable branch gate failed: "+failures.size());System.out.println("Unreachable branch check passed.");}
 private static void scan(Path base,List<String>failures)throws IOException{if(!Files.isDirectory(base))return;try(var paths=Files.walk(base)){for(Path path:paths.filter(Files::isRegularFile).filter(UnreachableBranchCheck::canonicalSource).toList()){String body=Files.readString(path);String code=body.replaceAll("(?s)/\\*.*?\\*/"," ").replaceAll("(?m)//.*$"," ");Matcher constant=CONSTANT.matcher(code);while(constant.find())failures.add(path+": constant branch "+constant.group());}}}
 private static boolean canonicalSource(Path path){String value=path.toString().replace('\\','/');String lower=value.toLowerCase(Locale.ROOT);if(lower.contains("/target/")||lower.contains("/build/")||lower.contains("/test/")||lower.contains("/legacy")||lower.contains("/compatibilityapp/"))return false;if(value.endsWith(".ts"))return true;if(!value.endsWith(".java"))return false;return value.contains("/src/main/java/com/aoo/");}
}
